const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={length:'长度',width:'宽度',height:'高度',hot:'热端温度',cold:'冷端温度',matrix:'基体热导率',filler:'填料热导率',resistance:'界面热阻',density:'密度',viscosity:'黏度',conductivity:'热导率',specificHeat:'比热',temperature:'温度',inlet:'入口速度',outlet:'出口压力',gap:'颗粒最小间隙',target:'目标填充率',radius:'半径',inletRadius:'入口半径',outletRadius:'出口半径'};
export function batchTargets(s){const result=[];for(const n of s.nodes.filter(n=>['micro','microCompute','macro'].includes(n.type))){const walk=(obj,path=[],depth=0)=>{if(depth>5)return;for(const [key,value]of Object.entries(obj||{})){if(/backup|previous|demo|version|source/i.test(key)||['molecule','materialNodes','seed','materialRef'].includes(key))continue;const parts=[...path,key];if(typeof value==='number'&&Number.isFinite(value))result.push({nodeId:n.id,path:parts.join('.'),label:n.name+' · '+parts.map(k=>labels[k]||({'materials':'材料','propertyConfigs':'物性配置','materialProperties':'物性配置','md':'MD','dft':'DFT','chains':'链数','start':'起始温度','end':'结束温度','equilibrium':'平衡温度','frames':'帧数','interval':'间隔','steps':'计算步数','modeling':'几何','primitives':'结构'})[k]||k).join(' / ')});else if(value&&typeof value==='object')walk(value,parts,depth+1);}};walk(n.params);}return result;}
export function batchValues(text){return String(text).trim().split(/[,，;；\s]+/).filter(Boolean).map(Number);}
export function batchIssues(p,s){const rows=p.rows||[],issues=[],targets=batchTargets(s),seen=new Set();if(!rows.length)issues.push('请至少添加一个参数');if(!['product','zip'].includes(p.mode))issues.push('请选择组合方式');for(const row of rows){const key=row.nodeId+':'+row.path;if(!targets.some(t=>t.nodeId===row.nodeId&&t.path===row.path))issues.push('参数目标已失效，请重新选择');if(seen.has(key))issues.push('同一参数不能重复设置');seen.add(key);const values=batchValues(row.values);if(!values.length||values.some(v=>!Number.isFinite(v)))issues.push('取值必须是数字，使用逗号分隔');}const lengths=rows.map(r=>batchValues(r.values).length);if(p.mode==='zip'&&new Set(lengths.filter(n=>n!==1)).size>1)issues.push('逐项配对时，各参数取值数量需相同，或仅填一个固定值');const count=p.mode==='zip'?Math.max(0,...lengths):lengths.reduce((a,b)=>a*b,1);if(count>500)issues.push('单组最多支持 500 次计算，请减少取值');return [...new Set(issues)];}
function factorialCombinations(p){const rows=p.rows||[];if(!rows.length)return [];const lists=rows.map(r=>batchValues(r.values));if(lists.some(v=>!v.length||v.some(x=>!Number.isFinite(x))))return [];const count=p.mode==='zip'?Math.max(...lists.map(v=>v.length)):lists.reduce((a,b)=>a*b.length,1);if(count>500)return [];const item=(row,value)=>({nodeId:row.nodeId,path:row.path,value});if(p.mode==='zip')return Array.from({length:count},(_,i)=>rows.map((r,j)=>item(r,lists[j][lists[j].length===1?0:i])));return rows.reduce((groups,r,i)=>groups.flatMap(g=>lists[i].map(value=>[...g,item(r,value)])),[[]]);}

const signature=p=>JSON.stringify([p.rows,p.doeMethod,p.samples,p.seed]);
export function generateDOE(p){
 const rows=p.rows||[];if(!rows.length)throw new Error('请先选择因子并设置取值');
 const lists=rows.map(r=>batchValues(r.values));if(lists.some(v=>!v.length||v.some(x=>!Number.isFinite(x))))throw new Error('请填写有效的因子水平或范围');
 if(p.doeMethod!=='lhs'){const count=lists.reduce((a,b)=>a*b.length,1);if(count>500)throw new Error('全因子设计超过 500 组，请减少水平或使用拉丁超立方');return factorialCombinations({...p,mode:'product'});}
 const count=Number(p.samples);if(!Number.isInteger(count)||count<2||count>500)throw new Error('采样数量需为 2–500 的整数');if(lists.some(v=>v.length!==2||v[0]>=v[1]))throw new Error('拉丁超立方的每个因子需输入两个递增数值：下限, 上限');
 let seed=Number(p.seed)||42;const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};const columns=lists.map(([low,high])=>{const values=Array.from({length:count},(_,i)=>Number((low+(i+random())/count*(high-low)).toPrecision(8)));for(let i=count-1;i>0;i--){const j=Math.floor(random()*(i+1));[values[i],values[j]]=[values[j],values[i]];}return values;});return Array.from({length:count},(_,i)=>rows.map((r,j)=>({nodeId:r.nodeId,path:r.path,value:columns[j][i]})));
}
export function batchCombinations(p){if(p.design)return p.design.signature===signature(p)?p.design.groups:[];return factorialCombinations(p);}
export function openBatchParameters(openDialog,s,node,{locked='',onSave}){
 const draft=structuredClone(node.params),targets=batchTargets(s);draft.rows??=[];draft.doeMethod??='factorial';draft.samples??=20;draft.seed??=42;
 const d=openDialog(`<form class="dialog-form batch-parameter-form"><header class="doe-dialog-heading"><h2>因子设计</h2><p class="binding-note">选择因子并设置水平或范围，一键生成 DOE 实验矩阵。</p></header><div class="doe-dialog-body"><section class="doe-configuration" aria-label="因子与设计设置"><h3>因子设置</h3><div data-batch-rows></div><button type="button" class="btn" data-batch-add>＋ 添加因子</button><h3 class="doe-method-heading">实验设计</h3><div class="doe-options"><label class="field"><span>设计方法</span><select data-doe-method><option value="factorial">全因子设计 · 离散水平全部组合</option><option value="lhs">拉丁超立方 · 连续范围均匀采样</option></select></label><label class="field"><span>采样数量</span><input type="number" min="2" max="500" data-doe-samples></label><label class="field"><span>随机种子</span><input type="number" data-doe-seed></label></div><button type="button" class="btn primary" data-doe-generate>生成 DOE 方案</button><p class="macro-error" role="alert"></p></section><section class="doe-results" aria-label="实验方案预览"><h3>实验矩阵</h3><section class="batch-preview" aria-live="polite"></section></section></div><div class="dialog-actions"><button type="button" class="btn" data-dialog-close>${locked?'关闭':'取消'}</button>${locked?'':'<button class="btn primary">应用实验方案</button>'}</div></form>`);d.classList.add('batch-parameter-dialog');
 const method=d.querySelector('[data-doe-method]'),samples=d.querySelector('[data-doe-samples]'),seed=d.querySelector('[data-doe-seed]');method.value=draft.doeMethod;samples.value=draft.samples;seed.value=draft.seed;
 const collect=()=>{draft.rows=[...d.querySelectorAll('[data-batch-row]')].map(row=>{const t=targets[Number(row.querySelector('select').value)];return {nodeId:t?.nodeId||'',path:t?.path||'',values:row.querySelector('input').value};});draft.doeMethod=method.value;draft.samples=Number(samples.value);draft.seed=Number(seed.value);draft.mode=method.value==='lhs'?'zip':'product';};
 const preview=()=>{samples.closest('label').hidden=method.value!=='lhs';seed.closest('label').hidden=method.value!=='lhs';samples.disabled=!!locked||method.value!=='lhs';seed.disabled=!!locked||method.value!=='lhs';const groups=batchCombinations(draft),generated=draft.design?.signature===signature(draft);d.querySelector('.batch-preview').innerHTML=`<strong>${generated?groups.length+' 组实验':'待生成 DOE 方案'}</strong><p class="binding-note">${method.value==='lhs'?'每个因子输入下限与上限，例如：20, 80。':'每个因子输入离散水平，例如：20, 40, 60。'} 修改因子后需重新生成。</p>${generated?`<div class="doe-table"><table><thead><tr><th>实验</th>${draft.rows.map(r=>`<th>${esc(targets.find(t=>t.nodeId===r.nodeId&&t.path===r.path)?.label||r.path)}</th>`).join('')}</tr></thead><tbody>${groups.slice(0,50).map((g,i)=>`<tr><td>${i+1}</td>${g.map(v=>`<td>${esc(v.value)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><small>展示前 ${Math.min(50,groups.length)} 组，共 ${groups.length} 组；完整矩阵随任务保存。</small>`:''}`;};
 const render=()=>{d.querySelector('[data-batch-rows]').innerHTML=draft.rows.map((r,i)=>`<div data-batch-row class="batch-parameter-row"><label class="field"><span>因子 ${i+1}</span><select aria-label="因子 ${i+1}">${targets.map((t,j)=>`<option value="${j}" ${t.nodeId===r.nodeId&&t.path===r.path?'selected':''}>${esc(t.label)}</option>`).join('')}</select></label><label class="field"><span>水平 / 范围</span><input aria-label="因子 ${i+1}水平" value="${esc(r.values)}" placeholder="例如：20, 40, 60"></label><button type="button" class="btn" data-batch-remove="${i}">删除</button></div>`).join('');if(locked)d.querySelectorAll('input,select,button:not([data-dialog-close])').forEach(el=>el.disabled=true);preview();};
 d.querySelector('[data-batch-add]').onclick=()=>{collect();const t=targets.find(t=>!draft.rows.some(r=>r.nodeId===t.nodeId&&r.path===t.path));if(t){draft.rows.push({nodeId:t.nodeId,path:t.path,values:''});render();}};
 d.querySelector('[data-batch-rows]').onclick=e=>{const b=e.target.closest('[data-batch-remove]');if(b&&!locked){collect();draft.rows.splice(Number(b.dataset.batchRemove),1);render();}};
 const generate=()=>{collect();const errors=batchIssues({...draft,design:undefined},s).filter(x=>!x.includes('500'));if(errors.length)throw new Error(errors.join('；'));const groups=generateDOE(draft);draft.design={signature:signature(draft),groups};preview();};
 d.querySelector('[data-doe-generate]').onclick=()=>{try{generate();d.querySelector('.macro-error').textContent='';}catch(e){d.querySelector('.macro-error').textContent=e.message;}};
 d.querySelector('form').oninput=d.querySelector('form').onchange=()=>{collect();preview();};d.querySelector('form').onsubmit=e=>{e.preventDefault();if(locked)return;collect();if(!draft.design||draft.design.signature!==signature(draft)){d.querySelector('.macro-error').textContent='请先生成当前因子的 DOE 方案';return;}onSave(draft);d.close();};render();
}
